// Asset catalog + cached importer. Catalog entries come from assets/core/catalog.json (bundled, searchable, with licence fields).
// Procedural entries are generated by assetlib.js. External GLBs are supported by register()/ensure(): they are size-limited, cached, normalised to metres with
// the pivot on the floor, and refused unless source, license and licenseEvidence are filled in -- no file is used without a recorded right to use it.
import * as THREE from 'three';
import catalogJson from '../../assets/core/catalog.json';
import { makeLib } from './assetlib.js';

const MAX_GLB = 8 * 1024 * 1024;
const ID = /^[a-z0-9][a-z0-9._-]{1,63}$/;

export class Assets {
  constructor(shared) {
    this.lib = makeLib(shared); this.items = new Map(); this.cache = new Map(); this.loads = 0; this.pending = new Map(); this.made = new Set();
    for (const a of catalogJson.assets) this.items.set(a.id, { ...catalogJson.defaults, ...a });
  }
  has(id) { return this.items.has(id); }
  loaded() { return this.made.size + this.cache.size; }
  meta(id) { const m = this.items.get(id); if (!m) throw Object.assign(new Error(`Unknown asset "${id}". Run {"cmd":"asset.catalog"} for the list.`), { code: 'asset.unknown', path: 'assetId' }); return m; }
  // size [w,h,d] in metres, measured from the real geometry once and cached
  size(id) {
    const m = this.meta(id); if (m._size) return m._size;
    const o = this.instantiate(id), b = new THREE.Box3().setFromObject(o), s = b.getSize(new THREE.Vector3()); m._size = [+s.x.toFixed(3), +s.y.toFixed(3), +s.z.toFixed(3)]; m._tris = 0;
    o.traverse(n => { if (n.isMesh) { const g = n.geometry; m._tris += (g.index ? g.index.count : g.attributes.position.count) / 3; } }); return m._size;
  }
  summary(m) { return { id: m.id, name: m.name, category: m.category, tags: m.tags, size: this.size(m.id), tris: Math.round(m._tris), format: m.format, license: m.license, source: m.source }; }
  query({ query, tags, category, limit } = {}) {
    const q = String(query || '').toLowerCase().trim(), tg = [].concat(tags || []).map(s => String(s).toLowerCase());
    const hit = [...this.items.values()].filter(m => (!category || m.category === category) && tg.every(t => m.tags.includes(t)) && (!q || [m.id, m.name, ...m.tags].some(s => s.toLowerCase().includes(q))));
    return hit.slice(0, Math.min(200, Math.max(1, +limit || 50))).map(m => this.summary(m));
  }
  inspect(id) { const m = this.meta(id); return { ...this.summary(m), licenseEvidence: m.licenseEvidence, anchors: m.anchors || [], collider: m.collider || 'none', bounds: this.size(id), ...(m.url ? { url: m.url } : {}) }; }
  // fresh Object3D for one placement. Procedural assets are built from shared geometry; GLBs are cloned from the cached template (placeholder box until loaded).
  instantiate(id) {
    const m = this.meta(id);
    if (m.format === 'glb') {
      const t = this.cache.get(id); if (t) return t.clone(true);
      const p = new THREE.Group(); const ph = new THREE.Mesh(new THREE.BoxGeometry(...(m.size || [1, 1, 1])), new THREE.MeshBasicMaterial({ color: 0xff4fa3, wireframe: true })); ph.position.y = (m.size || [1, 1, 1])[1] / 2; p.add(ph); p.userData.pending = id; return p;
    }
    const gen = this.lib.gen[id]; if (!gen) throw Object.assign(new Error(`Asset "${id}" has no generator.`), { code: 'asset.generator' });
    this.made.add(id); const g = gen(); g.userData.assetId = id; return g;
  }
  // an external GLB: needs source, license and licenseEvidence, a url (http(s) or same-origin or blob:), and stays under the size cap
  register(meta) {
    const need = ['id', 'name', 'category', 'url', 'source', 'license', 'licenseEvidence'], miss = need.filter(k => !meta[k]);
    if (miss.length) throw Object.assign(new Error('asset.register needs ' + miss.join(', ') + '. A file without a recorded licence is not used.'), { code: 'asset.license' });
    if (!ID.test(meta.id)) throw Object.assign(new Error('asset id must be lowercase letters, digits, . _ -'), { code: 'asset.invalid' });
    if (this.items.has(meta.id)) throw Object.assign(new Error(`asset "${meta.id}" already exists`), { code: 'asset.duplicate' });
    if (!/^(https?:|blob:|\.?\/|[a-z0-9_.-]+\/)/i.test(meta.url)) throw Object.assign(new Error('asset url must be http(s), blob: or a relative path'), { code: 'asset.invalid' });
    this.items.set(meta.id, { tags: [], collider: 'none', gpu: {}, ...meta, format: 'glb' }); return this.items.get(meta.id);
  }
  async ensure(id) {
    const m = this.meta(id); if (m.format !== 'glb' || this.cache.has(id)) return true;
    if (this.pending.has(id)) return this.pending.get(id);
    const p = (async () => {
      const res = await fetch(m.url); if (!res.ok) throw Object.assign(new Error(`Could not load ${m.url} (${res.status}).`), { code: 'asset.load' });
      const buf = await res.arrayBuffer(); if (buf.byteLength > MAX_GLB) throw Object.assign(new Error(`${id} is ${(buf.byteLength / 1048576).toFixed(1)} MB; the limit is ${MAX_GLB / 1048576} MB.`), { code: 'asset.size' });
      const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
      const gltf = await new GLTFLoader().parseAsync(buf, String(m.url).replace(/[^/]*$/, ''));
      const root = gltf.scene; root.updateMatrixWorld(true);
      const b = new THREE.Box3().setFromObject(root), c = b.getCenter(new THREE.Vector3()), k = m.scale || 1;
      const wrap = new THREE.Group(); root.position.set(-c.x, -b.min.y, -c.z); wrap.add(root); wrap.scale.setScalar(k);
      wrap.traverse(n => { if (n.isMesh) n.castShadow = n.receiveShadow = true; }); wrap.userData.assetId = id;
      this.cache.set(id, wrap); this.loads++; delete m._size; return true;
    })().finally(() => this.pending.delete(id));
    this.pending.set(id, p); return p;
  }
}
